    callback31()
    local function callback32()
        _G.VD_FarmStatusLabel = nil
        _G.VD_SetFarmToggle = nil
        _G.VD_SetKillerFarmToggle = nil
        _G.VD_SetTotalAFKToggle = nil
        _G.VD_SetHopEscapeToggle = nil
        _G.VD_SetInstantEscapeToggle = nil
        _G.VD_DoCancelGen = nil
        do
            createSection(tabFarm, "Survivor Automations", UI.Accent)
            local autoFarmSurvivor = createCollapsibleToggle(tabFarm, "Survivor Auto Farm", settingsValue.AutoFarmSurvivor, function(autoFarmSurvivor2)
                if autoFarmSurvivor2 then
                    if settingsValue.AutoFarmAFKTotal then
                        settingsValue.AutoFarmAFKTotal = false
                        if _G.VD_SetTotalAFKToggle then
                            _G.VD_SetTotalAFKToggle(false)
                        end
                    end
                    if settingsValue.AutoServerHopEscape then
                        settingsValue.AutoServerHopEscape = false
                        if _G.VD_SetHopEscapeToggle then
                            _G.VD_SetHopEscapeToggle(false)
                        end
                    end
                    if settingsValue.InstantFinishlineEscape then
                        settingsValue.InstantFinishlineEscape = false
                        if _G.VD_SetInstantEscapeToggle then
                            _G.VD_SetInstantEscapeToggle(false)
                        end
                    end
                end
                settingsValue.AutoFarmSurvivor = autoFarmSurvivor2
                if autoFarmSurvivor2 then
                    _G.VD_FarmState.farmTeamStartTime = tick()
